            for neighbour, _ in graph[path[-1]]:
                if distances[neighbour] + graph[neighbour][path[-1]][1] == distances[path[-1]]:
                    path.append(neighbour)
                    break
        path.reverse()
        return path
    return (distances[target], reconstruct_path(graph, source, target, distances))
